#!/usr/bin/env python3
from __future__ import annotations

import argparse
import base64
import datetime as dt
import importlib.util
import py_compile
import shutil
import subprocess
import sys
from pathlib import Path

VERSION = "0.13.2"

BROKEN = base64.b64decode("").decode("utf-8")
FIXED = base64.b64decode("").decode("utf-8")
NOTE = base64.b64decode("").decode("utf-8")

GEN_REL = Path("tools/generate_llm_context_map.py")
NOTE_REL = Path("docs/llm_context/updates/v1320_context_generator_hotfix.md")


def resolve_roots(frontend_arg: str | None, backend_arg: str | None):
    cwd = Path.cwd().resolve()
    fe_candidates = []
    be_candidates = []

    if frontend_arg:
        fe_candidates.append(Path(frontend_arg).expanduser().resolve())
    if backend_arg:
        be_candidates.append(Path(backend_arg).expanduser().resolve())

    fe_candidates += [
        cwd,
        cwd / "LambdaVisionSuper",
        cwd.parent / "LambdaVisionSuper",
    ]
    be_candidates += [
        cwd,
        cwd / "LambdaVisionSuperBackEnd",
        cwd.parent / "LambdaVisionSuperBackEnd",
    ]

    frontend = next(
        (
            p for p in fe_candidates
            if (p / "src/Pages/ComputerVisionPage.tsx").exists()
            and (p / GEN_REL).exists()
        ),
        None,
    )
    backend = next(
        (
            p for p in be_candidates
            if (p / "app/services/vision_app/models.py").exists()
        ),
        None,
    )

    if frontend is None:
        raise RuntimeError(
            "Cannot locate LambdaVisionSuper frontend. "
            "Use --frontend /path/to/LambdaVisionSuper"
        )
    if backend is None:
        raise RuntimeError(
            "Cannot locate LambdaVisionSuperBackEnd. "
            "Use --backend /path/to/LambdaVisionSuperBackEnd"
        )

    return frontend, backend


def generator_state(frontend: Path) -> str:
    path = frontend / GEN_REL
    if not path.exists():
        return "MISSING"
    text = path.read_text(encoding="utf-8")
    if text == FIXED:
        return "OK"
    if text == BROKEN:
        return "UPDATE"
    return "CONFLICT"


def note_state(frontend: Path) -> str:
    path = frontend / NOTE_REL
    if not path.exists():
        return "CREATE"
    return "OK" if path.read_text(encoding="utf-8") == NOTE else "CONFLICT"


def scan(frontend: Path, backend: Path):
    print("=" * 104)
    print("COMPUTER VISION V0.13.2 — CONTEXT GENERATOR HOTFIX")
    print("=" * 104)
    print(f"Frontend : {frontend}")
    print(f"Backend  : {backend}")
    print()
    print(f"  [{generator_state(frontend):12}] frontend/{GEN_REL.as_posix()}")
    print(f"  [{note_state(frontend):12}] frontend/{NOTE_REL.as_posix()}")
    print()
    print("v0.13.2 contract:")
    print("  Fix SyntaxError: unterminated string literal in context generator")
    print("  Split v0.13.1 architecture summary into valid Python strings")
    print("  Update summary to match current behavior:")
    print("    - one camera per workspace")
    print("    - keyboard.* live endpoints")
    print("    - simulator drivers legacy-hidden")
    print("  No runtime / API / IDE behavior changes")
    return 0


def preflight(frontend: Path):
    gs = generator_state(frontend)
    ns = note_state(frontend)
    errors = []
    if gs not in {"UPDATE", "OK"}:
        errors.append(f"frontend/{GEN_REL.as_posix()}: {gs}")
    if ns not in {"CREATE", "OK"}:
        errors.append(f"frontend/{NOTE_REL.as_posix()}: {ns}")
    if errors:
        raise RuntimeError("Safe hotfix stopped:\n  - " + "\n  - ".join(errors))


def regenerate_context(frontend: Path, backend: Path):
    generator = frontend / GEN_REL
    cmd = [
        sys.executable,
        str(generator),
        "--frontend",
        str(frontend),
        "--backend",
        str(backend),
    ]
    if "--output-dir" in generator.read_text(encoding="utf-8"):
        cmd.extend(["--output-dir", str(frontend / "docs/llm_context")])

    proc = subprocess.run(
        cmd,
        cwd=str(frontend),
        text=True,
        capture_output=True,
    )
    if proc.returncode != 0:
        raise RuntimeError(
            "Context generator failed:\n"
            + (proc.stdout + "\n" + proc.stderr).strip()
        )
    if proc.stdout.strip():
        print(proc.stdout.strip())


def apply(frontend: Path, backend: Path):
    preflight(frontend)

    stamp = dt.datetime.now().strftime("%Y%m%d_%H%M%S")
    backup_root = (
        frontend
        / ".lambda_updater_backups"
        / f"computer_vision_v1320_{stamp}"
    )
    backup_root.mkdir(parents=True, exist_ok=True)

    gen = frontend / GEN_REL
    if gen.exists():
        dst = backup_root / "frontend" / GEN_REL
        dst.parent.mkdir(parents=True, exist_ok=True)
        shutil.copy2(gen, dst)

    note = frontend / NOTE_REL
    if note.exists():
        dst = backup_root / "frontend" / NOTE_REL
        dst.parent.mkdir(parents=True, exist_ok=True)
        shutil.copy2(note, dst)

    if gen.read_text(encoding="utf-8") != FIXED:
        gen.write_text(FIXED, encoding="utf-8")
        print(f"[WRITE] frontend/{GEN_REL.as_posix()}")

    note.parent.mkdir(parents=True, exist_ok=True)
    if not note.exists() or note.read_text(encoding="utf-8") != NOTE:
        note.write_text(NOTE, encoding="utf-8")
        print(f"[WRITE] frontend/{NOTE_REL.as_posix()}")

    print("[INFO] Regenerating LLM context docs...")
    regenerate_context(frontend, backend)

    print(f"[OK] Backup: {backup_root}")
    print("Run verify next.")
    return 0


def verify(frontend: Path, backend: Path, skip_build: bool = False):
    print("=" * 104)
    print("VERIFY COMPUTER VISION V0.13.2")
    print("=" * 104)
    failures = 0

    gen = frontend / GEN_REL

    try:
        py_compile.compile(str(gen), doraise=True)
        print("[OK] Context generator Python syntax")
    except Exception as exc:
        print(f"[FAIL] Context generator Python syntax: {exc}")
        failures += 1

    text = gen.read_text(encoding="utf-8")
    checks = [
        ("One-camera-per-workspace summary", "each workspace binds exactly one declared camera" in text),
        ("Keyboard endpoint summary", "keyboard.space / enter / escape / arrows / F1-F12" in text),
        ("Simulator legacy-hidden summary", "simulator drivers remain legacy-hidden" in text),
        ("Hotfix handoff note", (frontend / NOTE_REL).exists()),
        ("v0.13.1 code present", (backend / "tests/vision_app/test_vision_app_v1310.py").exists()),
    ]
    for label, ok in checks:
        print(f"[{'OK' if ok else 'FAIL'}] {label}")
        failures += 0 if ok else 1

    try:
        regenerate_context(frontend, backend)
        print("[OK] LLM context regeneration")
    except Exception as exc:
        print(f"[FAIL] LLM context regeneration: {exc}")
        failures += 1

    if importlib.util.find_spec("pytest") is not None and (backend / "tests/vision_app").exists():
        full_ready = (
            (backend / "app/core").exists()
            and (backend / "app/services/vision_labs").exists()
        )
        targets = (
            ["tests/vision_app"]
            if full_ready
            else ["tests/vision_app/test_vision_app_v1310.py"]
        )
        proc = subprocess.run(
            [sys.executable, "-m", "pytest", "-q", *targets],
            cwd=str(backend),
            text=True,
            capture_output=True,
        )
        if proc.returncode == 0:
            print("[OK] Vision App regression tests")
            if proc.stdout.strip():
                print(proc.stdout.strip())
        else:
            print("[FAIL] Vision App regression tests")
            print((proc.stdout + "\n" + proc.stderr).strip())
            failures += 1
    else:
        print("[SKIP] pytest / Vision App tests unavailable")

    if not skip_build and (frontend / "package.json").exists() and (frontend / "node_modules").exists():
        proc = subprocess.run(["npm", "run", "build"], cwd=str(frontend))
        if proc.returncode == 0:
            print("[OK] Frontend npm build")
        else:
            print("[FAIL] Frontend npm build")
            failures += 1
    else:
        print("[SKIP] Frontend npm build")

    if failures:
        print(f"[FAIL] v0.13.2 verification finished with {failures} issue(s).")
        return 1

    print("[OK] Computer Vision v0.13.2 context hotfix verified.")
    return 0


def main():
    parser = argparse.ArgumentParser()
    parser.add_argument("command", choices=["scan", "apply", "verify"])
    parser.add_argument("--frontend")
    parser.add_argument("--backend")
    parser.add_argument("--skip-build", action="store_true")
    args = parser.parse_args()

    try:
        frontend, backend = resolve_roots(args.frontend, args.backend)
        if args.command == "scan":
            return scan(frontend, backend)
        if args.command == "apply":
            return apply(frontend, backend)
        return verify(frontend, backend, skip_build=args.skip_build)
    except Exception as exc:
        print(f"[ERROR] {exc}")
        return 2


if __name__ == "__main__":
    raise SystemExit(main())
